<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Возмещение ущерба — СБ</title><link rel="stylesheet" href="site-theme.css">
<style>
*{box-sizing:border-box}body{margin:0;background:#f3f8f7;color:#1a3438;font:14px/1.5 Inter,Arial,sans-serif}.page{max-width:1180px;margin:auto;padding:24px 16px 48px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.top h1{font-size:24px;margin:0}.top a,.btn{border:1px solid #d5e5e2;border-radius:9px;padding:9px 13px;background:#fff;color:#214347;text-decoration:none;font-weight:700;cursor:pointer}.btn.primary{background:#08777b;border-color:#08777b;color:#fff}.panel{background:#fff;border:1px solid #e0ebe8;border-radius:14px;padding:17px;margin-bottom:14px}.form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}.field{display:flex;flex-direction:column;gap:5px}.field.wide{grid-column:1/-1}.field label{font-size:12px;font-weight:700;color:#597578}.field input,.field select,.field textarea{width:100%;border:1px solid #d8e6e3;border-radius:9px;padding:10px;font:inherit}.field textarea{min-height:75px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:780px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e8efed;font-size:12px}th{color:#668085;background:#f8fbfa}td strong{font-size:13px}.balance{font-weight:800;color:#a34c32}.muted{color:#71888a;font-size:12px}.error{color:#b44335}.success{color:#27734a}.actions{display:flex;gap:6px;flex-wrap:wrap}@media(max-width:700px){.form{grid-template-columns:1fr 1fr}.field.wide{grid-column:1/-1}.top{align-items:flex-start;flex-direction:column}}
</style></head><body><main class="page">
<div class="top"><div><h1>Контроль возмещения ущерба</h1><div class="muted">Установленная сумма, заявлено к возмещению, фактически возмещено и остаток</div></div><a href="index.html">На главную</a></div>
<section class="panel" id="editor" hidden><h2 style="margin:0 0 12px;font-size:17px" id="formTitle">Новая запись</h2><form id="damageForm" class="form">
<input type="hidden" name="id" id="recordId" value="0">
<div class="field"><label>Торговый объект</label><select name="object_id" id="objectId" required></select></div>
<div class="field"><label>Наименование / основание</label><input name="title" id="title" maxlength="180" required></div>
<div class="field"><label>Установленный ущерб, ₽</label><input name="established_amount" id="established" type="number" min="0" step="0.01" value="0"></div>
<div class="field"><label>Заявлено к возмещению, ₽</label><input name="claimed_amount" id="claimed" type="number" min="0" step="0.01" value="0"></div>
<div class="field"><label>Фактически возмещено, ₽</label><input name="reimbursed_amount" id="reimbursed" type="number" min="0" step="0.01" value="0"></div>
<div class="field"><label>Связанный инцидент (необязательно)</label><input name="incident_id" id="incidentId" type="number" min="0" placeholder="ID инцидента"></div>
<div class="field wide"><label>Примечание</label><textarea name="notes" id="notes" maxlength="5000"></textarea></div>
<div class="field wide actions"><button class="btn primary" type="submit">Сохранить</button><button class="btn" type="button" id="cancelEdit">Очистить</button><span id="formMessage" class="muted"></span></div>
</form></section>
<section class="panel"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><h2 style="margin:0;font-size:17px">Реестр ущерба</h2><button class="btn" id="refresh" type="button">Обновить</button></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>Объект / основание</th><th>Установлено</th><th>Заявлено</th><th>Возмещено</th><th>Остаток</th><th>Обновлено</th><th></th></tr></thead><tbody id="rows"><tr><td colspan="7">Загрузка...</td></tr></tbody></table></div></section>
</main><script>
const api=a=>'api.php?action='+encodeURIComponent(a),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let csrf='',canManage=false;
const money=v=>Number(v||0).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽';
async function load(){const [r1,r2]=await Promise.all([fetch(api('damage_data'),{credentials:'same-origin'}),fetch(api('dashboard_data'),{credentials:'same-origin'})]);const d=await r1.json(),dash=await r2.json();if(!r1.ok||!d.ok){document.getElementById('rows').innerHTML='<tr><td colspan="7">'+esc(d.error||'Ошибка загрузки')+'</td></tr>';return;}csrf=d.csrf||'';canManage=!!d.can_manage;
 if(canManage){document.getElementById('editor').hidden=false;const objs=dash.objects||[];document.getElementById('objectId').innerHTML=objs.map(o=>'<option value="'+Number(o.id)+'">'+esc(o.name)+'</option>').join('');}
 const rows=document.getElementById('rows');rows.innerHTML=d.damage_cases.length?d.damage_cases.map(x=>'<tr><td><strong>'+esc(x.title)+'</strong><div class="muted">'+esc(x.object_name)+(x.incident_id?' · Инцидент #'+Number(x.incident_id):'')+'</div><div class="muted">'+esc(x.notes||'')+'</div></td><td>'+money(x.established_amount)+'</td><td>'+money(x.claimed_amount)+'</td><td>'+money(x.reimbursed_amount)+'</td><td class="balance">'+money(x.balance)+'</td><td>'+esc(x.updated_at)+'</td><td>'+(canManage?'<button class="btn edit" data-id="'+Number(x.id)+'">Изменить</button>':'')+'</td></tr>').join(''):'<tr><td colspan="7" class="muted">Записей пока нет.</td></tr>';
 window.damageRows=d.damage_cases;
}
function clearForm(){document.getElementById('damageForm').reset();document.getElementById('recordId').value='0';document.getElementById('formTitle').textContent='Новая запись';}
document.getElementById('cancelEdit').addEventListener('click',clearForm);
document.getElementById('rows').addEventListener('click',e=>{const b=e.target.closest('.edit');if(!b)return;const x=(window.damageRows||[]).find(v=>Number(v.id)===Number(b.dataset.id));if(!x)return;document.getElementById('recordId').value=x.id;document.getElementById('objectId').value=x.object_id;document.getElementById('title').value=x.title;document.getElementById('established').value=x.established_amount;document.getElementById('claimed').value=x.claimed_amount;document.getElementById('reimbursed').value=x.reimbursed_amount;document.getElementById('incidentId').value=x.incident_id||'';document.getElementById('notes').value=x.notes||'';document.getElementById('formTitle').textContent='Изменение записи #'+x.id;window.scrollTo({top:0,behavior:'smooth'});});
document.getElementById('damageForm').addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,fd=new FormData(f),body=Object.fromEntries(fd.entries());body.csrf=csrf;for(const k of ['id','object_id','incident_id'])body[k]=Number(body[k]||0);for(const k of ['established_amount','claimed_amount','reimbursed_amount'])body[k]=Number(body[k]||0);const m=document.getElementById('formMessage');m.textContent='Сохранение...';try{const r=await fetch(api('damage_save'),{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Ошибка');m.className='success';m.textContent='Сохранено';clearForm();await load();}catch(err){m.className='error';m.textContent=err.message;}});
document.getElementById('refresh').addEventListener('click',load);load();
</script></body></html>